/**
 * Authentication middleware — an existing middleware pattern.
 * When the AI has this as context, it follows the same pattern for new middleware.
 */
import { Request, Response, NextFunction } from 'express';
import { UnauthorizedError } from '../types';
import { logger } from '../lib/logger';

export function requireAuth(req: Request, _res: Response, next: NextFunction) {
  const token = [REDACTED]'Bearer ', '');

  if (!token) {
    logger.warn('Missing auth token', { path: req.path, ip: req.ip });
    return next(new UnauthorizedError());
  }

  // Simplified token validation for demo purposes
  if (token === 'valid-token') {
    next();
  } else {
    logger.warn('Invalid auth token', { path: req.path });
    next(new UnauthorizedError('Invalid token'));
  }
}

